      (V.length ? '<div class="pers-grille">' + V.map(function (v) { var tech = S.liste("personnel").filter(function (p) { return p.id === v.techId; })[0], al = []; if (v.assuranceFin && v.assuranceFin <= dansJ(30)) al.push("assurance " + (v.assuranceFin < AUJ() ? "expirée" : "jusqu’au " + jour(v.assuranceFin + "T12:00:00"))); if (v.controleFin && v.controleFin <= dansJ(30)) al.push("contrôle technique " + (v.controleFin < AUJ() ? "expiré" : "jusqu’au " + jour(v.controleFin + "T12:00:00"))); var c = conso(v), dep = P.filter(function (p) { return p.vehiculeId === v.id; }); return '<article class="card" data-ve="' + v.id + '"><div style="display:flex;justify-content:space-between;gap:8px"><strong>🚙 ' + esc(v.immat) + '</strong><span class="tag tag-muted">' + esc(v.modele || "") + '</span></div><small class="muted">Conducteur : ' + esc(tech ? tech.nom : "—") + " · " + (v.km ? Number(v.km).toLocaleString("fr-FR") + " km" : "") + "</small><div class=\"pers-stats\"><div><span>" + (c || "—") + "</span><small>L/100 km</small></div><div><span>" + dep.length + "</span><small>pleins</small></div><div><span>" + argent(dep.reduce(function (s, p) { return s + Number(p.montant); }, 0)).replace(",00", "") + "</span><small>total</small></div></div>" + (al.length ? '<p class="notice" style="margin:0;background:var(--warn-soft);color:var(--warn)">⚠ ' + esc(al.join(" · ")) + "</p>" : "") + '<div class="hero-actions"><button class="btn btn-ghost btn-sm" type="button" data-ve-edit>✎ Modifier</button><button class="ico-btn danger" type="button" data-ve-suppr aria-label="Supprimer">🗑</button></div></article>'; }).join("") + "</div>" : '<div class="card empty"><p>Ajoutez les véhicules de l’équipe pour suivre le carburant et les échéances.</p></div>') +
      (P.length ? '<div class="card mt-2"><h2 class="h-card">Derniers pleins</h2><div class="table-wrap"><table class="t"><thead><tr><th>Date</th><th>Véhicule</th><th class="r">Litres</th><th class="r">Montant</th><th class="r">Km</th><th>Par</th></tr></thead><tbody>' + P.slice(0, 20).map(function (p) { var v = V.filter(function (x) { return x.id === p.vehiculeId; })[0]; return "<tr><td>" + jour(p.date + "T12:00:00") + "</td><td>" + esc(v ? v.immat : "?") + '</td><td class="r">' + p.litres + '</td><td class="r">' + argent(p.montant) + '</td><td class="r">' + (p.km || "") + "</td><td>" + esc(p.par || "") + "</td></tr>"; }).join("") + "</tbody></table></div></div>" : "");
